using PaymentAuthorization.Domain;
using PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed class HttpPaymentGatewayTests
{
    private static async Task<(AuthorizationOutcome Outcome, FakeProviderServer Server)> Authorize(int status, string? body)
    {
        var server = await FakeProviderServer.StartAsync(status, body);
        var gateway = new HttpPaymentGateway(new HttpClient { BaseAddress = server.BaseAddress });
        var outcome = await gateway.AuthorizeAsync("ORD-7", new Money(12.50m, "eur"), CancellationToken.None);
        return (outcome, server);
    }

    [Fact]
    public async Task The_authorization_is_posted_as_json_with_reference_amount_and_currency()
    {
        var (_, server) = await Authorize(200, """{"status":"approved"}""");
        await using var _ = server;

        var request = Assert.Single(server.Requests);
        Assert.Equal("POST", request.Method);
        Assert.Equal("/v1/authorizations", request.Path);
        Assert.StartsWith("application/json", request.ContentType);
        using var json = JsonDocument.Parse(request.Body);
        var root = json.RootElement;
        Assert.Equal(["amount", "currency", "reference"], root.EnumerateObject().Select(p => p.Name).Order().ToArray());
        Assert.Equal("ORD-7", root.GetProperty("reference").GetString());
        Assert.Equal(12.50m, root.GetProperty("amount").GetDecimal());
        Assert.Equal("EUR", root.GetProperty("currency").GetString());
    }

    [Fact]
    public async Task An_approved_answer_is_read_as_approved()
    {
        var (outcome, server) = await Authorize(200, """{"status":"approved"}""");
        await using var _ = server;

        Assert.Equal(AuthorizationOutcome.Approved, outcome);
    }

    [Fact]
    public async Task A_declined_answer_is_read_as_declined()
    {
        var (outcome, server) = await Authorize(200, """{"status":"declined"}""");
        await using var _ = server;

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task Extra_fields_in_the_answer_are_ignored()
    {
        var (outcome, server) = await Authorize(200, """{"id":"a1","status":"approved","risk":{"score":3}}""");
        await using var _ = server;

        Assert.Equal(AuthorizationOutcome.Approved, outcome);
    }

    [Fact]
    public async Task A_refusal_with_402_is_a_decline()
    {
        var (outcome, server) = await Authorize(402, """{"error":"insufficient_funds"}""");
        await using var _ = server;

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Theory]
    [InlineData(400)]
    [InlineData(401)]
    [InlineData(422)]
    [InlineData(500)]
    [InlineData(503)]
    public async Task Other_error_statuses_are_surfaced_not_mistaken_for_a_decision(int status)
    {
        var server = await FakeProviderServer.StartAsync(status, """{"status":"approved"}""");
        await using var _ = server;
        var gateway = new HttpPaymentGateway(new HttpClient { BaseAddress = server.BaseAddress });

        await Assert.ThrowsAsync<HttpRequestException>(() =>
            gateway.AuthorizeAsync("ORD-7", new Money(5, "EUR"), CancellationToken.None));
    }

    [Theory]
    [InlineData("""{"status":"pending"}""")]
    [InlineData("""{"result":"approved"}""")]
    [InlineData("""{"status":"APPROVED"}""")]
    [InlineData("null")]
    public async Task An_answer_that_is_not_an_explicit_approval_never_counts_as_approved(string body)
    {
        var (outcome, server) = await Authorize(200, body);
        await using var _ = server;

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task A_body_that_is_not_json_is_surfaced_as_an_error()
    {
        var server = await FakeProviderServer.StartAsync(200, "<html>oops</html>");
        await using var _ = server;
        var gateway = new HttpPaymentGateway(new HttpClient { BaseAddress = server.BaseAddress });

        await Assert.ThrowsAnyAsync<Exception>(() =>
            gateway.AuthorizeAsync("ORD-7", new Money(5, "EUR"), CancellationToken.None));
    }
}
